import{_ as a,o,c as r,a2 as s}from"./chunks/framework.1C62pOns.js";const n="/pro-agent-hub-installer/capturas/es/login.png",t="/pro-agent-hub-installer/capturas/es/layout.png",l="/pro-agent-hub-installer/capturas/es/dashboard.png",f=JSON.parse('{"title":"Primeros pasos","description":"","frontmatter":{},"headers":[],"relativePath":"es/interface/primeiros-passos.md","filePath":"es/interface/primeiros-passos.md","lastUpdated":1791313012000}'),i={name:"es/interface/primeiros-passos.md"};function p(c,e,u,d,m,g){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="primeros-pasos" tabindex="-1">Primeros pasos <a class="header-anchor" href="#primeros-pasos" aria-label="Permalink to &quot;Primeros pasos&quot;">​</a></h1><h2 id="entrar" tabindex="-1">Entrar <a class="header-anchor" href="#entrar" aria-label="Permalink to &quot;Entrar&quot;">​</a></h2><p><img src="'+n+'" alt="login"></p><p>El acceso es por correo y contraseña. Si la instalación acaba de subir, el usuario inicial lo crea el instalador — su contraseña está en la salida de <code>install.sh</code>.</p><p><strong>Olvidé mi contraseña</strong> envía un enlace por correo, así que solo funciona después de configurar el SMTP en <a href="/pro-agent-hub-installer/es/interface/administracao#configuración">Configuración</a>. En una instalación nueva, antes de eso, la recuperación no tiene por dónde salir.</p><p><strong>Crear cuenta</strong> registra un usuario sin ningún grupo. Entra y no ve casi nada — es el comportamiento correcto: quien da acceso es un master, vinculando al usuario a un grupo.</p><h2 id="el-menu" tabindex="-1">El menú <a class="header-anchor" href="#el-menu" aria-label="Permalink to &quot;El menú&quot;">​</a></h2><p><img src="'+t+'" alt="layout"></p><p>El menú lateral está dividido por tema: <strong>Principal</strong> (el día a día), <strong>Configuración IA</strong> (lo que alimenta a los agentes), <strong>Integraciones</strong> y <strong>Administración</strong>. Los tres últimos solo aparecen para usuarios master.</p><p>Se puede plegar a una franja de iconos; al pasar el ratón, el submenú aparece flotando. La búsqueda de arriba filtra los elementos del menú por nombre — útil cuando la instalación tiene muchas Apps.</p><p><strong>Tus Apps aparecen en el menú</strong>, justo debajo de Principal, como elementos propios — no dentro de una pantalla que las lista. Para quien la usa, &quot;Formulario de Encuesta&quot; es un elemento del menú como cualquier otro, no &quot;una App dentro del App Builder&quot;.</p><h2 id="el-panel" tabindex="-1">El panel <a class="header-anchor" href="#el-panel" aria-label="Permalink to &quot;El panel&quot;">​</a></h2><p><img src="'+l+'" alt="dashboard"></p><p>El consumo de IA del mes arriba — tokens, coste, el presupuesto del modelo más cerca del límite y el modelo que más consume —, los contadores de la plataforma justo debajo y los gráficos: tokens por día en los últimos 30 días (el coste del día aparece al pasar el ratón), tokens por modelo y por origen (chat o workflow) en el mes, y las ejecuciones de workflow por estado. El mes anterior aparece escrito, no como porcentaje: a mitad de mes, la comparación en % siempre parecería una caída.</p><p>Es un resumen, no una herramienta de operación: para seguir un workflow en marcha, la pantalla es <a href="/pro-agent-hub-installer/es/interface/workflows#ejecuciones">Ejecuciones</a>; para el detalle de consumo y coste, es <a href="/pro-agent-hub-installer/es/interface/administracao#consumo-de-tokens">Consumo de tokens</a>.</p><h2 id="tema-e-idioma" tabindex="-1">Tema e idioma <a class="header-anchor" href="#tema-e-idioma" aria-label="Permalink to &quot;Tema e idioma&quot;">​</a></h2><p>Al pie del menú están el selector de tema (claro/oscuro) y el de idioma. La plataforma habla portugués, inglés y español; la elección es por usuario y persiste entre sesiones.</p>',17)])])}const b=a(i,[["render",p]]);export{f as __pageData,b as default};
